syntax:
template <class ForwardIt> 
ForwardIt algorithm(ForwardIt first, ForwardIt last); 
// where algorithm is a mutating function such as std::shuffle, std::reverse, std::swap_ranges, etc.

code_example:
#include <algorithm>
#include <vector>
#include <random>
#include <iostream>

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    // Create a random device and generator for shuffling
    std::random_device rd;
    std::mt19937 gen(rd());
    // Shuffle the elements in the vector
    std::shuffle(data.begin(), data.end(), gen);
    // Reverse the order of elements
    std::reverse(data.begin(), data.end());
    // Swap ranges within the vector
    std::swap_ranges(data.begin(), data.begin() + 2, data.end() - 2);
    // Output the resulting vector
    for (int n : data) {
        std::cout << n << ' ';
    }
    return 0;
}
